use vstd::prelude::*;

verus! {

    /// bmat concatenates four vectors of equal length into one vector of length 4·n,
    /// in the order: top_left, top_right, bottom_left, bottom_right.
    fn bmat(
        top_left: Vec<f32>,
        top_right: Vec<f32>,
        bottom_left: Vec<f32>,
        bottom_right: Vec<f32>,
    ) -> (result: Vec<f32>)
        requires
            // all four inputs have the same length
            top_right.len() == top_left.len(),
            bottom_left.len() == top_left.len(),
            bottom_right.len() == top_left.len(),
        ensures
            // the result has length 4·n
            result.len() == top_left.len() * 4,
            // and its contents are exactly the concatenation
            // of the four inputs, in order
            result@ == top_left@ + top_right@ + bottom_left@ + bottom_right@,
    {
        let n = top_left.len();
        debug_assert_eq!(top_right.len(), n);
        debug_assert_eq!(bottom_left.len(), n);
        debug_assert_eq!(bottom_right.len(), n);

        // Pre‐allocate exactly 4·n slots
        let mut result = Vec::with_capacity(n * 4);

        // Move each input vector's elements into result in order
        result.extend(top_left);
        result.extend(top_right);
        result.extend(bottom_left);
        result.extend(bottom_right);

        result
    }

}

